#include <stdio.h>
/* Deterministic reference controller. Times and current envelopes are in the task.
 * Revised for a 47 uF buffer: the first frame is placed after the storage
 * charge-settling time (~1.2 s at 47 uF), then frames are spaced 4 s apart
 * (>3x the measured burst-recharge time) so all four land by t=14 s. */
int main(void) {
    puts("t_s,duration_s,state,seq,value,crc");
    for (unsigned seq = 1; seq <= 4; ++seq) {
        double start = 2.0 + 4.0 * (seq - 1);
        unsigned value = 2500;
        unsigned crc = (seq ^ value ^ 0xA5) & 255;
        printf("%.6f,0.010000,sample,%u,%u,%u\n", start, seq, value, crc);
        printf("%.6f,0.004000,tx,%u,%u,%u\n", start + 0.011, seq, value, crc);
    }
    return 0;
}

#include <stdio.h>
/* Stress probe (EXP-E): the two leading frames are drawn 20 ms apart so the
 * buffer must supply both bursts with effectively no recharge in between.
 * This is the conservative proxy for a short vibration/harvest dropout and it
 * makes the two-frame droop a directly observable metric. Storage is R6's 47 uF.
 * Absolute times, and the 10 ms sample / 4 ms tx durations, come from the task;
 * the pair is placed at R6's own first-frame time so the measurement bites. */
int main(void) {
    puts("t_s,duration_s,state,seq,value,crc");
    static const double t[4] = {2.000, 2.020, 6.000, 10.000};
    for (unsigned seq = 1; seq <= 4; ++seq) {
        unsigned value = 2500;
        unsigned crc = (seq ^ value ^ 0xA5) & 255;
        printf("%.6f,0.010000,sample,%u,%u,%u\n", t[seq - 1], seq, value, crc);
        printf("%.6f,0.004000,tx,%u,%u,%u\n", t[seq - 1] + 0.011, seq, value, crc);
    }
    return 0;
}

#include <stdio.h>
/* Deterministic reference controller (R7 service schedule, unchanged from R6).
 * Times and current envelopes are in the task. Frames sit at 2/6/10/14 s:
 * the first frame is later than the 68 uF charge-settling time (~1.6 s) and the
 * 4 s spacing is >3x the measured burst-recharge time (~1.0-1.2 s). */
int main(void) {
    puts("t_s,duration_s,state,seq,value,crc");
    for (unsigned seq = 1; seq <= 4; ++seq) {
        double start = 2.0 + 4.0 * (seq - 1);
        unsigned value = 2500;
        unsigned crc = (seq ^ value ^ 0xA5) & 255;
        printf("%.6f,0.010000,sample,%u,%u,%u\n", start, seq, value, crc);
        printf("%.6f,0.004000,tx,%u,%u,%u\n", start + 0.011, seq, value, crc);
    }
    return 0;
}
